import { describe, expect, it, vi } from 'vitest';
import { pollInstalledStatus } from '../../src/renderer/shared/installStatus';

describe('onboarding install status polling', () => {
  it('keeps probing after installer completion until the CLI is detected', async () => {
    const refreshStatus = vi.fn()
      .mockResolvedValueOnce({ installed: false })
      .mockResolvedValueOnce({ installed: false })
      .mockResolvedValueOnce({ installed: true, version: '1.2.3' });
    const wait = vi.fn(async () => undefined);

    const status = await pollInstalledStatus(refreshStatus, {
      initialInstalled: { installed: false },
      maxPolls: 5,
      intervalMs: 25,
      wait,
    });

    expect(status).toEqual({ installed: true, version: '1.2.3' });
    expect(refreshStatus).toHaveBeenCalledTimes(3);
    expect(wait).toHaveBeenCalledTimes(2);
    expect(wait).toHaveBeenCalledWith(25);
  });

  it('returns null after the bounded retry window without one extra delay', async () => {
    const refreshStatus = vi.fn(async () => ({ installed: false }));
    const wait = vi.fn(async () => undefined);

    const status = await pollInstalledStatus(refreshStatus, {
      maxPolls: 3,
      wait,
    });

    expect(status).toBeNull();
    expect(refreshStatus).toHaveBeenCalledTimes(3);
    expect(wait).toHaveBeenCalledTimes(2);
  });
});

/**
 * Shared Electron launcher helper for Playwright E2E tests.
 *
 * Wraps `_electron.launch()` with:
 * - Correct path to the built main.js entry point (.vite/build/main.js)
 * - Isolated userData dir per test run (prevents session bleed)
 * - Verbose startup logging
 * - Clean teardown helper
 *
 * Usage in specs:
 *   import { launchApp, teardownApp, AppHandle } from '../setup/electron-launcher';
 *
 *   let app: AppHandle;
 *   test.beforeAll(async () => { app = await launchApp(); });
 *   test.afterAll(async () => { await teardownApp(app); });
 *
 * ---------------------------------------------------------------------------
 * CRITICAL: DO NOT PASS executablePath
 * ---------------------------------------------------------------------------
 * Playwright's `_electron.launch()` ONLY injects its internal `-r <loader>`
 * bootstrap arg when `executablePath` is NOT set. The loader hijacks
 * `app.whenReady()` and signals `__playwright_run` back to the test harness.
 * Passing `executablePath` skips the loader → `launch()` hangs for the full
 * timeout (30s) even though the Electron process starts correctly.
 *
 * Playwright uses `require('electron/index.js')` internally to resolve the
 * local electron binary — the same path that `node_modules/.bin/electron`
 * points to — just with the bootstrap loader wired in.
 *
 * See: https://github.com/microsoft/playwright/blob/main/packages/playwright/src/electron/electron.ts
 */

import { _electron as electron, ElectronApplication, Page } from '@playwright/test';
import path from 'node:path';
import fs from 'node:fs';
import os from 'node:os';
import { MY_APP_DIR } from './playwright.config';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const LOG_PREFIX = '[ElectronLauncher]';
const LAUNCH_TIMEOUT_MS = 30_000;

/** Entry point — built by `npm run build` (Electron Forge's vite build). */
const MAIN_JS_ENTRY = path.join(MY_APP_DIR, '.vite', 'build', 'main.js');

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface LaunchOptions {
  /**
   * Override the built main.js entry. Defaults to
   * `app/.vite/build/main.js`. Useful for integration tests that launch
   * a development entry point.
   */
  mainEntry?: string;
  /**
   * Override userData directory. If not set, a fresh temp dir is created for
   * each launch to provide full test isolation.
   */
  userDataDir?: string;
  /**
   * Extra environment variables to pass to the Electron process.
   */
  env?: Record<string, string>;
  /**
   * Extra args forwarded to the app (after the entry point).
   */
  args?: string[];
}

export interface AppHandle {
  electronApp: ElectronApplication;
  /** First BrowserWindow page (shell or onboarding) */
  firstWindow: Page;
  /** Ephemeral userData dir created for this launch (cleaned up by teardownApp) */
  userDataDir: string;
  /** Whether the userDataDir was created by the launcher (should be deleted on teardown) */
  cleanupUserData: boolean;
}

// ---------------------------------------------------------------------------
// launchApp
// ---------------------------------------------------------------------------

/**
 * Launch the Electron application for E2E testing.
 * Returns an AppHandle with the running ElectronApplication and first window.
 *
 * NOTE: Tests run against the vite-built main.js. Run `npm run build`
 * (or `npm run package`) in app/ before executing e2e tests.
 */
export async function launchApp(opts: LaunchOptions = {}): Promise<AppHandle> {
  const mainEntry = opts.mainEntry ?? MAIN_JS_ENTRY;

  if (!fs.existsSync(mainEntry)) {
    throw new Error(
      `${LOG_PREFIX} Built main.js not found at ${mainEntry}. ` +
        `Run \`npm run build\` in app/ before running E2E tests.`,
    );
  }

  let cleanupUserData = false;
  let userDataDir = opts.userDataDir ?? '';
  if (!userDataDir) {
    userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'agb-test-'));
    cleanupUserData = true;
    console.log(`${LOG_PREFIX} Created ephemeral userData: ${userDataDir}`);
  }

  console.log(`${LOG_PREFIX} Launching with main entry: ${mainEntry}`);
  console.log(`${LOG_PREFIX} userData: ${userDataDir}`);

  const launchEnv: Record<string, string> = {
    ...process.env as Record<string, string>,
    // Force dev mode so agentic://diagnostics is available
    DEV_MODE: '1',
    // Prevent system keychain dialogs in CI
    KEYCHAIN_MOCK: '1',
    // Ensure telemetry writes locally only
    POSTHOG_API_KEY: '',
    ...opts.env,
  };

  // CRITICAL: DO NOT pass executablePath here — see file header.
  // Playwright resolves electron via `require('electron/index.js')` and
  // injects its loader that signals __playwright_run.
  const electronApp = await electron.launch({
    args: [
      mainEntry,
      `--user-data-dir=${userDataDir}`,
      '--no-sandbox',
      '--disable-gpu',
      '--remote-debugging-port=0',
      ...(opts.args ?? []),
    ],
    env: launchEnv,
    timeout: LAUNCH_TIMEOUT_MS,
    cwd: MY_APP_DIR,
  });

  console.log(`${LOG_PREFIX} App launched. Waiting for first window...`);

  const firstWindow = await electronApp.firstWindow();
  await firstWindow.waitForLoadState('domcontentloaded');

  console.log(
    `${LOG_PREFIX} First window ready. Title: "${await firstWindow.title()}"`,
  );

  return { electronApp, firstWindow, userDataDir, cleanupUserData };
}

// ---------------------------------------------------------------------------
// teardownApp
// ---------------------------------------------------------------------------

/**
 * Gracefully close the Electron app and clean up ephemeral userData.
 */
export async function teardownApp(handle: AppHandle): Promise<void> {
  console.log(`${LOG_PREFIX} Tearing down app...`);
  try {
    await handle.electronApp.close();
  } catch (err) {
    console.warn(`${LOG_PREFIX} Close error (ignored): ${(err as Error).message}`);
  }

  if (handle.cleanupUserData && handle.userDataDir) {
    try {
      fs.rmSync(handle.userDataDir, { recursive: true, force: true });
      console.log(`${LOG_PREFIX} Cleaned up userData: ${handle.userDataDir}`);
    } catch (err) {
      console.warn(`${LOG_PREFIX} Failed to clean userData: ${(err as Error).message}`);
    }
  }
}

// ---------------------------------------------------------------------------
// Utility: evaluate in main process
// ---------------------------------------------------------------------------

/**
 * Execute a function in the Electron main process and return its result.
 * Useful for asserting IPC state, reading session files, etc.
 */
export async function evalInMain<T>(
  handle: AppHandle,
  fn: () => T,
): Promise<T> {
  return handle.electronApp.evaluate(fn);
}

/**
 * Playwright configuration for The Browser E2E tests.
 *
 * Tests run against the BUILT Electron artifact (not `npm start`).
 * Build first: npm run make
 * Then run: npm run e2e
 *
 * Track H owns this file.
 */

import { defineConfig } from '@playwright/test';
import path from 'node:path';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const REPO_ROOT = path.resolve(__dirname, '../../..');
const MY_APP_ROOT = path.join(REPO_ROOT, 'app');

/**
 * Path to the built Electron app on macOS (arm64 or x64).
 * Electron Forge puts the output under out/app-darwin-{arch}/app.app
 * We detect arch at runtime.
 */
function getElectronAppPath(): string {
  const arch = process.arch === 'arm64' ? 'arm64' : 'x64';
  return path.join(
    MY_APP_ROOT,
    'out',
    `app-darwin-${arch}`,
    'app.app',
    'Contents',
    'MacOS',
    'app',
  );
}

export const ELECTRON_APP_PATH = getElectronAppPath();
export const MY_APP_DIR = MY_APP_ROOT;

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

export default defineConfig({
  testDir: path.join(MY_APP_ROOT, 'tests', 'e2e'),
  timeout: 90_000,           // 90s per test; golden path must finish in <60s
  expect: { timeout: 15_000 },
  fullyParallel: false,      // Electron tests share the display; run serially
  retries: 0,                // No auto-retry — flaky tests must be fixed at root
  workers: 1,
  reporter: [
    ['list'],
    ['json', { outputFile: path.join(MY_APP_ROOT, 'tests', 'results', 'e2e-report.json') }],
  ],
  use: {
    // Electron-specific options are passed in each spec via electron-launcher.ts
    // Playwright screenshot on failure for easier debugging
    screenshot: 'only-on-failure',
    trace: 'retain-on-failure',
  },
  projects: [
    {
      name: 'electron-e2e',
      testMatch: '**/*.spec.ts',
    },
  ],
});

import fs from 'node:fs';
import path from 'node:path';
import { afterAll, beforeEach, describe, expect, test, vi } from 'vitest';

const mockState = vi.hoisted(() => {
  const fsMod = require('node:fs') as typeof import('node:fs');
  const osMod = require('node:os') as typeof import('node:os');
  const pathMod = require('node:path') as typeof import('node:path');
  return {
    userData: fsMod.mkdtempSync(pathMod.join(osMod.tmpdir(), 'bu-harness-bootstrap-')),
  };
});

vi.mock('electron', () => ({
  app: {
    getPath: vi.fn(() => mockState.userData),
  },
}));

const {
  agentSkillDir,
  bootstrapHarness,
  browserHarnessJsDir,
  helpersPath,
  interactionSkillsDir,
  skillIdToPath,
  skillPath,
  skillPathFromMeta,
  toolsPath,
  userSkillsDir,
} = await import('../../../src/main/hl/harness');

describe('bootstrapHarness browser-harness-js materialization', () => {
  beforeEach(() => {
    fs.rmSync(path.join(mockState.userData, 'harness'), { recursive: true, force: true });
  });

  afterAll(() => {
    fs.rmSync(mockState.userData, { recursive: true, force: true });
  });

  test('writes Browser Harness JS runtime and removes legacy TOOLS.json', () => {
    fs.mkdirSync(path.dirname(toolsPath()), { recursive: true });
    fs.writeFileSync(toolsPath(), '{}\n');

    bootstrapHarness();

    const cli = path.join(browserHarnessJsDir(), 'sdk', 'browser-harness-js');
    const cliCmd = path.join(browserHarnessJsDir(), 'sdk', 'browser-harness-js.cmd');
    const agentSkill = path.join(agentSkillDir(), 'agent-skill');
    const userSkill = path.join(userSkillsDir(), 'general', 'existing', 'SKILL.md');
    fs.mkdirSync(path.dirname(userSkill), { recursive: true });
    fs.writeFileSync(userSkill, '# Existing\n');

    bootstrapHarness();

    expect(fs.existsSync(helpersPath())).toBe(true);
    expect(fs.readFileSync(skillPath(), 'utf-8')).toContain('Browser Harness JS');
    expect(fs.existsSync(toolsPath())).toBe(false);
    expect(fs.existsSync(cli)).toBe(true);
    expect(fs.existsSync(agentSkill)).toBe(true);
    expect(fs.existsSync(path.join(agentSkillDir(), 'agent-skill.cmd'))).toBe(true);
    expect(fs.existsSync(userSkill)).toBe(true);
    // Windows launcher ships alongside the bash script so Codex can find it
    // via PATHEXT (.CMD) instead of hitting the no-handler popup on the
    // extensionless bash file.
    expect(fs.existsSync(cliCmd)).toBe(true);
    expect(fs.readFileSync(cliCmd, 'utf-8')).toContain('bash.exe');
    expect(fs.existsSync(path.join(interactionSkillsDir(), 'screenshots.md'))).toBe(true);
    // Executable-bit assert: skipped on Windows because NTFS permission
    // mapping doesn't expose POSIX exec bits the way the test asserts.
    if (process.platform !== 'win32') {
      expect(fs.statSync(cli).mode & 0o111).not.toBe(0);
      expect(fs.statSync(agentSkill).mode & 0o111).not.toBe(0);
    }
  });

  test('rejects traversal and absolute skill IDs before converting to paths', () => {
    const root = path.join(mockState.userData, 'harness');

    expect(skillIdToPath('domain/github/repo', root)).toBe(path.join(root, 'domain-skills', 'github/repo.md'));
    expect(skillIdToPath('interaction/screenshots.md', root)).toBe(path.join(root, 'interaction-skills', 'screenshots.md'));
    expect(skillIdToPath("'domain/github/repo'", root)).toBe(path.join(root, 'domain-skills', 'github/repo.md'));
    expect(skillIdToPath('"interaction/screenshots.md"', root)).toBe(path.join(root, 'interaction-skills', 'screenshots.md'));
    expect(skillIdToPath('domain/../secret', root)).toBeNull();
    expect(skillIdToPath('domain/./github', root)).toBeNull();
    expect(skillIdToPath('domain//github', root)).toBeNull();
    expect(skillIdToPath('/domain/github', root)).toBeNull();
    expect(skillIdToPath('domain/C:/secret', root)).toBeNull();
    expect(skillPathFromMeta({ domain: 'user', topic: '../secret' }, root)).toBeNull();
    expect(skillPathFromMeta({ domain: 'domain', topic: '/github/repo' }, root)).toBeNull();
  });
});

import { describe, expect, it } from 'vitest';
import { installerSpawnSpec, runInstallCommand } from '../../../src/main/hl/engines/installer';

const posixIt = process.platform === 'win32' ? it.skip : it;

function nodeCommand(script: string): string {
  return `${JSON.stringify(process.execPath)} -e ${JSON.stringify(script)}`;
}

describe('engine installer background runner', () => {
  it('routes Windows installs through hidden cmd.exe without opening a terminal', () => {
    const command = 'npm install -g @openai/codex';

    const spec = installerSpawnSpec(command, {
      platform: 'win32',
      env: {
        Path: 'C:\\Windows\\System32',
        ComSpec: 'C:\\Windows\\System32\\cmd.exe',
      },
    });

    expect(spec.command).toBe('C:\\Windows\\System32\\cmd.exe');
    expect(spec.args).toEqual(['/d', '/s', '/c', command]);
    expect(spec.spawnOptions).toEqual({ windowsHide: true });
    expect(spec.args.join(' ')).not.toContain('start');
    expect(spec.args.join(' ')).not.toContain('Installer');
  });

  it('routes POSIX installs through a background shell command runner', () => {
    const command = 'curl -fsSL https://claude.ai/install.sh | bash';

    const spec = installerSpawnSpec(command, {
      platform: 'linux',
      env: { PATH: '/usr/bin' },
    });

    expect(spec.command).toBe('sh');
    expect(spec.args).toEqual(['-lc', command]);
    expect(spec.spawnOptions).toEqual({});
  });

  it('resolves after the installer process exits successfully', async () => {
    const result = await runInstallCommand(
      'Test Installer',
      nodeCommand("process.stdout.write('installed');"),
      { timeoutMs: 5000 },
    );

    expect(result).toMatchObject({
      opened: true,
      completed: true,
      exitCode: 0,
      signal: null,
      displayName: 'Test Installer',
    });
    expect(result.stdout).toContain('installed');
    expect(result.error).toBeUndefined();
  });

  it('returns installer stderr and exit code when the process fails', async () => {
    const result = await runInstallCommand(
      'Test Installer',
      nodeCommand("process.stderr.write('no permission'); process.exit(7);"),
      { timeoutMs: 5000 },
    );

    expect(result).toMatchObject({
      opened: false,
      completed: true,
      exitCode: 7,
      signal: null,
      displayName: 'Test Installer',
      stderr: 'no permission',
      error: 'no permission',
    });
  });

  posixIt('uses the signal in the fallback error when the installer is externally killed', async () => {
    const result = await runInstallCommand(
      'Test Installer',
      'kill -TERM $$',
      { timeoutMs: 5000 },
    );

    expect(result).toMatchObject({
      opened: false,
      completed: true,
      exitCode: null,
      signal: 'SIGTERM',
      displayName: 'Test Installer',
      error: 'Test Installer installer exited from signal SIGTERM',
    });
  });
});

import Module from 'node:module';
import { afterEach, describe, expect, it, vi } from 'vitest';

const keytarMocks = vi.hoisted(() => ({
  getPassword: vi.fn(),
  setPassword: vi.fn(async () => undefined),
  deletePassword: vi.fn(async () => false),
}));

vi.mock('../../../src/main/logger', () => ({
  mainLogger: { debug: vi.fn(), info: vi.fn(), warn: vi.fn(), error: vi.fn() },
}));

vi.mock('../../../src/main/identity/claudeCodeAuth', () => ({
  probeClaudeAuthStatus: vi.fn(async () => ({ loggedIn: false, subscriptionType: null })),
}));

const originalRequire = Module.prototype.require;

describe('authStore BrowserCode normalization', () => {
  afterEach(() => {
    Module.prototype.require = originalRequire;
    vi.clearAllMocks();
    vi.resetModules();
  });

  it('trims provider ids and active provider when loading the BrowserCode store blob', async () => {
    vi.resetModules();
    Module.prototype.require = function patchedRequire(this: NodeJS.Module, id: string) {
      if (id === 'keytar') return keytarMocks;
      return originalRequire.call(this, id);
    };
    keytarMocks.getPassword.mockResolvedValue(JSON.stringify({
      browserCode: {
        keys: {
          ' moonshotai ': {
            apiKey: '  secret-key  ',
            lastModel: ' moonshotai/kimi-k2.6 ',
          },
        },
        active: ' moonshotai ',
      },
    }));

    const authStore = await import('../../../src/main/identity/authStore');

    await expect(authStore.loadBrowserCodeStore()).resolves.toEqual({
      keys: {
        moonshotai: {
          apiKey: 'secret-key',
          lastModel: 'moonshotai/kimi-k2.6',
        },
      },
      active: 'moonshotai',
    });
    await expect(authStore.loadBrowserCodeConfig()).resolves.toEqual({
      providerId: 'moonshotai',
      model: 'moonshotai/kimi-k2.6',
      apiKey: 'secret-key',
    });
  });
});

